const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({executablePath:'/usr/bin/chromium', headless:true, args:['--no-sandbox','--disable-gpu']});
  const page = await browser.newPage({viewport:{width:390,height:844}, deviceScaleFactor:1, isMobile:true, hasTouch:true});
  const errors=[]; page.on('pageerror', e=>errors.push(e.message));
  await page.goto('http://localhost:3002', {waitUntil:'networkidle'});
  const initial = await page.locator('#board').evaluate(el=>({count:el.children.length, size:el.getAttribute('aria-label'), width:el.clientWidth, overflow:document.documentElement.scrollWidth>innerWidth}));
  const arrangement = await page.locator('#board').evaluate(el=>[...el.children].map(c=>c.getAttribute('aria-label')||'empty').join('|'));
  const adjacent = await page.locator('.tile').filter({has:page.locator('.empty')}).count().catch(()=>-1);
  const emptyIndex = await page.locator('#board').evaluate(el=>[...el.children].findIndex(c=>c.classList.contains('empty')));
  const indexToMove = await page.locator('#board').evaluate(el=>{const a=[...el.children], e=a.findIndex(c=>c.classList.contains('empty')); return [e-3,e+3,e-1,e+1].find(i=>i>=0&&i<a.length&&Math.abs(Math.floor(i/3)-Math.floor(e/3))+Math.abs(i%3-e%3)===1)});
  await page.locator('#board').locator('.tile').nth(indexToMove < emptyIndex ? indexToMove : indexToMove-1).click();
  await page.waitForTimeout(1100);
  const afterMove = {moves:await page.locator('#moves').textContent(), time:await page.locator('#timer').textContent()};
  await page.locator('#resetButton').click();
  const reset = {moves:await page.locator('#moves').textContent(), time:await page.locator('#timer').textContent(), same:arrangement===await page.locator('#board').evaluate(el=>[...el.children].map(c=>c.getAttribute('aria-label')||'empty').join('|'))};
  await page.locator('[data-size="4"]').click();
  const four = await page.locator('#board').evaluate(el=>({count:el.children.length,label:el.getAttribute('aria-label')}));
  await page.screenshot({path:'screenshots/little-pieces-mobile.jpg',type:'jpeg',quality:82});
  console.log(JSON.stringify({initial,afterMove,reset,four,errors},null,2));
  await browser.close();
})();
